#include <stdio.h>

void min_max(const int *arr, int n, int *min, int *max) {
    *min = arr[0];
    *max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < *min) *min = arr[i];
        if (arr[i] > *max) *max = arr[i];
    }
}

int main(void) {
    int n;
    int a[100];
    int mn, mx;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) return 1;
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    min_max(a, n, &mn, &mx);
    printf("min=%d max=%d\n", mn, mx);
    return 0;
}
